{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Pethidine has an absolute oral bioavailability of 61% in healthy volunteers, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Maraviroc has an absolute oral bioavailability of 23.1% in humans, above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Perindopril, a carboxylic acid-containing ACE inhibitor, has absolute oral bioavailability of 66–95%, supporting high F for this acid/amide/thiol-related scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Pidotimod, a carboxylic acid and amide-containing molecule, has oral bioavailability of 42–44% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ampicillin, a carboxylic acid-containing beta-lactam, has oral bioavailability of 62 ± 17%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Milnacipran has absolute oral bioavailability of 85 ± 3%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Perindoprilat systemic availability after oral perindopril was 19 ± 7% in young healthy subjects, a below-threshold value; however, this reflects metabolite formation from a prodrug rather than direct oral bioavailability of the acid, so it is only weakly contradictory.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer experimental analogues, including carboxylic acid-containing drugs (perindopril, ampicillin, pidotimod) and other diverse scaffolds, show oral bioavailability above 20%, often 40–95%. The query's carboxylic acid and thiol are consistent with captopril-like ACE inhibitors, which are orally bioavailable. The low logD prior is overridden by direct evidence. The single below-threshold perindoprilat record is weak because it reflects prodrug conversion. Therefore predict high F (>=20%).",
  "evidence_gaps": [
    "No direct oral bioavailability study for the exact query molecule; prediction relies on high-transfer analogues.",
    "The only below-threshold record (perindoprilat) is a metabolite-availability measurement after prodrug dosing, not direct oral bioavailability of the acid.",
    "Metabolic stability of the free thiol and possible first-pass conjugation are not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

